#include <memory>
#include <string>
#include <chrono>
#include <functional>
#include <variant>
#include <vector>
#include <cstring>
#include <atomic>
#include <mutex>

namespace cloud_sdk {

struct RateLimitConfig {
    uint32_t max_requests_per_second;
    uint32_t burst_capacity;
    uint32_t retry_max_attempts;
    double backoff_multiplier;
};

class TokenBucket {
    std::atomic<int64_t> tokens_;
    int64_t capacity_;
    std::chrono::steady_clock::time_point last_refill_;
    std::mutex refill_mutex_;
public:
    TokenBucket(int64_t capacity) : tokens_(capacity), capacity_(capacity),
        last_refill_(std::chrono::steady_clock::now()) {}

    bool try_consume(int64_t n = 1) {
        std::lock_guard<std::mutex> lock(refill_mutex_);
        refill();
        int64_t current = tokens_.load(std::memory_order_relaxed);
        if (current >= n) {
            tokens_.store(current - n, std::memory_order_relaxed);
            return true;
        }
        return false;
    }
private:
    void refill() {
        auto now = std::chrono::steady_clock::now();
        auto elapsed = std::chrono::duration_cast<std::chrono::milliseconds>(
            now - last_refill_).count();
        if (elapsed > 0) {
            int64_t new_tokens = elapsed * capacity_ / 1000;
            int64_t current = tokens_.load(std::memory_order_relaxed);
            tokens_.store(std::min(capacity_, current + new_tokens),
                         std::memory_order_relaxed);
            last_refill_ = now;
        }
    }
};

struct RequestContext {
    uint32_t attempt_number;
    uint32_t max_attempts;
    std::string endpoint;
    std::string auth_token;
};

// Response types from different service tiers
struct ServiceResponseV1 {
    int32_t status_code;
    char payload[256];
    uint32_t payload_length;
};

struct ServiceResponseV2 {
    int32_t status_code;
    uint64_t request_id;
    char payload[512];
    uint32_t payload_length;
    uint64_t server_timestamp;
};

// Internal unified response used after parsing
struct UnifiedResponse {
    int32_t status_code;
    std::string payload;
    uint64_t request_id;
    bool is_retryable;
};

using RawResponse = std::variant<ServiceResponseV1, ServiceResponseV2>;

class ResponseParser {
public:
    // Parse raw wire bytes into appropriate response type
    static RawResponse parse_wire_format(const void* data, size_t len, int version) {
        if (version == 2 && len >= sizeof(ServiceResponseV2)) {
            ServiceResponseV2 resp;
            std::memcpy(&resp, data, sizeof(ServiceResponseV2));
            return resp;
        } else {
            ServiceResponseV1 resp;
            std::memcpy(&resp, data, std::min(len, sizeof(ServiceResponseV1)));
            return resp;
        }
    }

    // Convert to unified format for retry logic
    static UnifiedResponse unify(const RawResponse& raw) {
        UnifiedResponse result{};
        // Here's where the type handling matters
        if (auto* v2 = std::get_if<ServiceResponseV2>(&raw)) {
            result.status_code = v2->status_code;
            result.payload = std::string(v2->payload, v2->payload_length);
            result.request_id = v2->request_id;
            result.is_retryable = (v2->status_code == 429 || v2->status_code >= 500);
        } else if (auto* v1 = std::get_if<ServiceResponseV1>(&raw)) {
            result.status_code = v1->status_code;
            result.payload = std::string(v1->payload, v1->payload_length);
            result.request_id = 0;
            result.is_retryable = (v1->status_code == 429 || v1->status_code >= 500);
        }
        return result;
    }
};

class RetryPolicy {
    RateLimitConfig config_;
    TokenBucket bucket_;
public:
    RetryPolicy(const RateLimitConfig& cfg)
        : config_(cfg), bucket_(cfg.burst_capacity) {}

    bool should_retry(const UnifiedResponse& resp, uint32_t attempt) {
        return resp.is_retryable && attempt < config_.retry_max_attempts;
    }

    std::chrono::milliseconds get_backoff(uint32_t attempt) {
        // Exponential backoff with jitter
        double base_ms = 100.0 * config_.backoff_multiplier;
        for (uint32_t i = 0; i < attempt; ++i) base_ms *= 2.0;
        return std::chrono::milliseconds(static_cast<int64_t>(base_ms));
    }

    bool acquire_token() { return bucket_.try_consume(); }
};

// The SDK client that orchestrates requests
class CloudClient {
    RetryPolicy policy_;
    int detected_version_;

    // Simulates receiving response from network layer
    // In production this would be async I/O
    std::vector<uint8_t> send_raw_request(const RequestContext& ctx) {
        // Stub: would do actual network I/O
        std::vector<uint8_t> response_bytes(sizeof(ServiceResponseV2), 0);
        return response_bytes;
    }

public:
    CloudClient(const RateLimitConfig& cfg, int service_version)
        : policy_(cfg), detected_version_(service_version) {}

    UnifiedResponse execute(const std::string& endpoint, const std::string& token) {
        RequestContext ctx{0, 3, endpoint, token};
        UnifiedResponse final_response{};

        while (ctx.attempt_number <= ctx.max_attempts) {
            if (!policy_.acquire_token()) {
                // Rate limited locally - treat as retryable
                final_response.status_code = 429;
                final_response.is_retryable = true;
            } else {
                auto raw_bytes = send_raw_request(ctx);

                // Critical: version detection uses the stored version,
                // but the actual wire data might be from a different version
                // after a service upgrade mid-connection
                auto parsed = ResponseParser::parse_wire_format(
                    raw_bytes.data(), raw_bytes.size(), detected_version_);

                // The unify step reads payload_length from the struct,
                // which may contain uninitialized/attacker-controlled data
                // when version mismatch causes type confusion
                final_response = ResponseParser::unify(parsed);
            }

            if (!policy_.should_retry(final_response, ctx.attempt_number)) {
                break;
            }
            ctx.attempt_number++;
        }
        return final_response;
    }

    // Version negotiation - can be influenced by MITM
    void update_detected_version(int version) {
        detected_version_ = version;
    }
};

} // namespace cloud_sdk

int main() {
    cloud_sdk::RateLimitConfig cfg{100, 10, 3, 1.5};
    cloud_sdk::CloudClient client(cfg, 2);

    // Simulate version downgrade attack: attacker sends V1-sized response
    // but client parses as V2, reading beyond actual data boundaries
    client.update_detected_version(1);

    auto response = client.execute("/api/v2/resources", "bearer_token_xyz");
    return response.status_code;
}
